using System;
using System.IO;
using System.Linq;
using Newtonsoft.Json.Linq;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;
public static class Native49FinalClosure {
 static string Folder()=>JObject.Parse(File.ReadAllText("Tools/URPMigration/FinalClosure-current.json")).Value<string>("stage");
 static void Ready(){if(System.Diagnostics.Process.GetCurrentProcess().Id!=118008||EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||EditorApplication.isUpdating)throw new Exception("Owned stopped ready PID required");for(int i=0;i<UnityEngine.SceneManagement.SceneManager.sceneCount;i++)if(UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).isDirty)throw new Exception("Dirty scene blocks exit");if(Resources.FindObjectsOfTypeAll<UnityEngine.Object>().Any(o=>EditorUtility.IsPersistent(o)&&EditorUtility.IsDirty(o)&&AssetDatabase.GetAssetPath(o).StartsWith("Assets/")&&(o is Material||o is GameObject)))throw new Exception("Dirty material/prefab blocks exit");}
 public static string Snapshot(){Ready();var profile=AssetDatabase.LoadAssetAtPath<VolumeProfile>("Assets/DefaultVolumeProfile.asset");var components=new JArray();foreach(var c in profile.components){var original=JObject.Parse(EditorJsonUtility.ToJson(c));var def=ScriptableObject.CreateInstance(c.GetType());try{components.Add(new JObject{["type"]=c.GetType().AssemblyQualifiedName,["current"]=original,["constructorDefault"]=JObject.Parse(EditorJsonUtility.ToJson(def))});}finally{UnityEngine.Object.DestroyImmediate(def);}}var p=PlayerSettings.GetPreloadedAssets();var r=new JObject{["utc"]=DateTime.UtcNow.ToString("o"),["pid"]=System.Diagnostics.Process.GetCurrentProcess().Id,["preloadedAssets"]=new JArray(p.Select(o=>o==null?null:AssetDatabase.GetAssetPath(o))),["forceInternetPermission"]=PlayerSettings.Android.forceInternetPermission,["defaultVolumeComponents"]=components,["limits"]="Read-only postbuild preload/native default-volume state. Temporary constructor-default objects destroyed; no saves/settings writes/render/import."};File.WriteAllText(Folder()+"/native-postbuild.json",r.ToString());return Folder()+"/native-postbuild.json";}
 public static string ScheduleExit(){Ready();var stage=Folder();if(File.Exists(stage+"/exit-request.json"))throw new Exception("One official exit only");File.WriteAllText(stage+"/exit-request.json",new JObject{["utc"]=DateTime.UtcNow.ToString("o"),["pid"]=118008,["method"]="One-shot EditorApplication.update Exit(0), no SaveAssets/global flush/forcekill"}.ToString());EditorApplication.CallbackFunction tick=null;tick=()=>{EditorApplication.update-=tick;Ready();File.WriteAllText(stage+"/exit-native-marker.json",new JObject{["utc"]=DateTime.UtcNow.ToString("o"),["pid"]=118008}.ToString());EditorApplication.Exit(0);};EditorApplication.update+=tick;return stage;}
}
